mapper.select:
SELECT

FROM mes_quality_task


        AND task_no LIKE CONCAT('%', #{param.taskNo}, '%')


        AND product_code = #{param.productCode}


        AND product_name LIKE CONCAT('%', #{param.productName}, '%')


        AND batch_no = #{param.batchNo}


        AND order_no = #{param.orderNo}


        AND workstation_code = #{param.workstationCode}


        AND inspector = #{param.inspector}


        AND status = #{param.status}


        AND result = #{param.result}


        AND inspection_type = #{param.inspectionType}


        AND urgent = #{param.urgent}


        AND workshop_code = #{param.workshopCode}


        AND line_code = #{param.lineCode}


        AND TIMESTAMPDIFF(MINUTE, create_time, NOW()) > 60
        AND status IN ('PENDING', 'INSPECTING')


        AND (TIMESTAMPDIFF(MINUTE, create_time, NOW()) <= 60
        OR status NOT IN ('PENDING', 'INSPECTING'))




        AND create_time >= #{param.createTimeStart}


        AND create_time <= #{param.createTimeEnd}


        AND inspection_date >= #{param.inspectionTimeStart}


        AND inspection_date <= #{param.inspectionTimeEnd}


        AND complete_time >= #{param.completeTimeStart}


        AND complete_time <= #{param.completeTimeEnd}


        AND DATE(inspection_date) >= #{param.startDate}


        AND DATE(inspection_date) <= #{param.endDate}




        ORDER BY urgent DESC, create_time DESC


        ORDER BY
        CASE WHEN status IN ('PENDING', 'INSPECTING') AND TIMESTAMPDIFF(MINUTE, create_time, NOW()) > 60
        THEN 0 ELSE 1 END,
        create_time ASC



            ORDER BY ${param.orderBy}

                ${param.orderDirection}



            ORDER BY create_time DESC

SELECT COUNT(1) AS total_tasks, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_tasks, SUM(CASE WHEN status = 'PENDING' THEN 1 ELSE 0 END) AS pending_tasks, SUM(CASE WHEN status = 'INSPECTING' THEN 1 ELSE 0 END) AS inspecting_tasks, SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled_tasks, SUM(quantity_checked) AS total_checked, SUM(quantity_qualified) AS total_qualified, SUM(quantity_defective) AS total_defective, CASE WHEN SUM(quantity_checked) > 0 THEN ROUND(SUM(quantity_qualified) * 100.0 / SUM(quantity_checked), 2) ELSE 0 END AS pass_rate, CASE WHEN SUM(quantity_checked) > 0 THEN ROUND(SUM(quantity_defective) * 1000000.0 / SUM(quantity_checked), 2) ELSE 0 END AS dpmo FROM mes_quality_task
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}

SELECT DATE(create_time) AS date, COUNT(1) AS task_count, SUM(quantity_checked) AS total_checked, SUM(quantity_qualified) AS total_qualified, SUM(quantity_defective) AS total_defective, CASE WHEN SUM(quantity_checked) > 0 THEN ROUND(SUM(quantity_qualified) * 100.0 / SUM(quantity_checked), 2) ELSE 0 END AS pass_rate FROM mes_quality_task
status = 'COMPLETED'
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY DATE(create_time) ORDER BY DATE(create_time)

SELECT product_code, product_name, COUNT(1) AS task_count, SUM(quantity_checked) AS total_checked, SUM(quantity_qualified) AS total_qualified, SUM(quantity_defective) AS total_defective, CASE WHEN SUM(quantity_checked) > 0 THEN ROUND(SUM(quantity_qualified) * 100.0 / SUM(quantity_checked), 2) ELSE 0 END AS pass_rate FROM mes_quality_task
status = 'COMPLETED'
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY product_code, product_name HAVING SUM(quantity_checked) > 0 ORDER BY pass_rate DESC LIMIT 10

SELECT inspector, COUNT(1) AS task_count, SUM(quantity_checked) AS total_checked, SUM(quantity_qualified) AS total_qualified, SUM(quantity_defective) AS total_defective, CASE WHEN SUM(quantity_checked) > 0 THEN ROUND(SUM(quantity_qualified) * 100.0 / SUM(quantity_checked), 2) ELSE 0 END AS pass_rate, AVG(TIMESTAMPDIFF(MINUTE, create_time, complete_time)) AS avg_complete_time FROM mes_quality_task
status = 'COMPLETED' AND inspector IS NOT NULL AND inspector != ''
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY inspector HAVING SUM(quantity_checked) > 0 ORDER BY pass_rate DESC

